It also works with [`MethodRouter`]s that require state:

```rust
use axum::{Router, routing::get, extract::State};

#[derive(Clone)]
struct AppState;

async fn handler(State(_state): State<AppState>) {
    // ...
}

async fn not_found() -> (axum::http::StatusCode, &'static str) {
    (axum::http::StatusCode::NOT_FOUND, "Not found")
}

let app = Router::new()
    .route("/foo", get(|| async { /* ... */ }))
    .fallback(get(handler).fallback(not_found))
    .with_state(AppState);
# async {
# hyper::Server::bind(&"".parse().unwrap()).serve(app.into_make_service()).await.unwrap();
